11	/**
12	 * NPU Memory Model for CPU Simulation
13	 *
14	 * Provides UB, L1, L0A, L0B, L0C memory buffers sized per NPU architecture.
15	 * TASSIGN maps tiles to offsets within these buffers based on TileType.
16	 *
17	 * Each thread gets its own independent NPUMemoryModel instance via
18	 * thread_local storage, accurately modeling the hardware where each
19	 * AICore has physically separate UB/L0 memory.
20	 *
21	 * Memory mapping:
22	 *   - Vec tiles   → UB (Unified Buffer)
23	 *   - Mat tiles   → L1
24	 *   - Left tiles  → L0A
25	 *   - Right tiles → L0B
26	 *   - Acc tiles   → L0C
27	 */
28	#ifndef PTO_NPU_MEMORY_MODEL_HPP
29	#define PTO_NPU_MEMORY_MODEL_HPP
30	
31	#include <cstddef>
32	#include <algorithm>
33	#include <cstdint>
34	#include <vector>
35	#include <pto/common/pto_tile.hpp>
36	
37	namespace pto {
38	
39	enum class NPUArch { A2A3, A5 };
40	
41	class NPUMemoryModel {
42	private:
43	    enum MemoryRegion {
44	        REG,    // Registers - simulates NPU registers
45	        UB,     // Unified Buffer - for Vec tiles
46	        L1,     // L1 Buffer - for Mat tiles
47	        L0A,    // L0A Buffer - for Left tiles
48	        L0B,    // L0B Buffer - for Right tiles
49	        L0C,    // L0C Buffer - for Acc tiles
50	        L0A_MX, // L0A Scale Buffer - for Left MX scale tiles
51	        L0B_MX, // L0B Scale Buffer - for Right MX scale tiles
52	        _MAX_REGIONS
53	    };
54	
55	public:
56	    // Architecture-specific memory sizes (bytes)
57	    using ArchMemorySizes = std::size_t[MemoryRegion::_MAX_REGIONS];
58	
59	private:
60	    // Memory sizes by architecture
61	    // A2/A3:
62	    // https://www.hiascend.com/doc_center/source/zh/canncommercial/80RC3/devguide/appdevg/sdpdevg/atlasprogramming_12_0003.html
63	    static inline constexpr ArchMemorySizes kA2A3MemorySizes = {
64	        16 * 8,     // REGISTERS 16 with 8 byte
65	        192 * 1024, // UB:  192 KB
66	        512 * 1024, // L1:  512 KB
67	        64 * 1024,  // L0A: 64 KB
68	        64 * 1024,  // L0B: 64 KB
69	        128 * 1024, // L0C: 128 KB
70	        4 * 1024,   // L0A_MX: 4 KB
71	        4 * 1024,   // L0B: 4 KB
72	    };
73	
74	    static inline constexpr ArchMemorySizes kA5MemorySizes = {
75	        16 * 8,     // REGISTERS 16 with 8 byte
76	        256 * 1024, // UB:  256 KB
77	        512 * 1024, // L1:  512 KB
78	        64 * 1024,  // L0A: 64 KB (placeholder - verify actual A5 spec)
79	        64 * 1024,  // L0B: 64 KB
80	        256 * 1024, // L0C: 256 KB
81	        4 * 1024,   // L0A_MX: 4 KB
82	        4 * 1024,   // L0B: 4 KB
83	    };
84	
85	public:
86	    // Each thread gets its own NPUMemoryModel instance, accurately modeling
87	    // the hardware where each AICore has physically separate memory.
88	    static NPUMemoryModel& Instance()
89	    {
90	        thread_local NPUMemoryModel instance;
91	        return instance;
92	    }
93	
94	    // Set the default architecture for all threads.
95	    // Call once before any thread uses Instance().
96	    static void SetDefaultArch(NPUArch arch) { defaultArch_ = arch; }
97	
98	    // Initialize with specific architecture (call once per thread at startup)
99	    void Initialize(NPUArch arch)
100	    {
101	        switch (arch) {
102	            case NPUArch::A2A3:
103	                // Yes, we know about memcpy, but CI does not allow it
104	                for (size_t i = 0; i < std::size(kA2A3MemorySizes); i++) {
105	                    sizes_[i] = kA2A3MemorySizes[i];
106	                }
107	                break;
108	            case NPUArch::A5:
109	                for (size_t i = 0; i < std::size(kA5MemorySizes); i++) {
110	                    sizes_[i] = kA5MemorySizes[i];
111	                }
112	                break;
113	        }
114	
115	        for (int i = 0; i < MemoryRegion::_MAX_REGIONS; i++) {
116	            buffers_[i].resize(sizes_[i], 0);
117	        }
118	        arch_ = arch;
119	        initialized_ = true;
120	    }
121	
122	    // Auto-initialize with default architecture if not already done
123	    void EnsureInitialized()
124	    {
125	        if (!initialized_) {
126	            Initialize(defaultArch_);
127	        }
128	    }
129	
130	    template <typename T>
131	    std::size_t GetNPUAddr(T* ptr)
132	    {
133	        const auto addr = reinterpret_cast<std::uintptr_t>(ptr);
134	        for (int region = 0; region < MemoryRegion::_MAX_REGIONS; ++region) {
135	            const auto start = reinterpret_cast<std::uintptr_t>(buffers_[region].data());
136	            const auto end = start + buffers_[region].size();
137	            if (addr >= start && addr < end) {
138	                return addr - start;
139	            }
140	        }
141	        throw std::invalid_argument("Cannot get proper NPU addr out of pointer");
142	    }
143	
144	    // Get pointer to memory at offset within a region
145	    template <typename TileDef>
146	    TileDef::DType* GetPointer(std::size_t byteOffset)
147	    {
148	        static_assert(is_tile_data_v<TileDef> || is_conv_tile_v<TileDef>);
149	        int numElem;
150	        if constexpr (is_tile_data_v<TileDef>) {
151	            numElem = TileDef::Numel;
152	        } else {
153	            numElem = TileDef::bufferSize / sizeof(typename TileDef::DType);
154	        }
155	        if constexpr (TileDef::Loc == TileType::Mat) {
156	            return GetPointer<typename TileDef::DType, MemoryRegion::L1>(byteOffset, numElem);
157	        } else if constexpr (TileDef::Loc == TileType::Left) {
158	            return GetPointer<typename TileDef::DType, MemoryRegion::L0A>(byteOffset, numElem);
159	        } else if constexpr (TileDef::Loc == TileType::Right) {
160	            return GetPointer<typename TileDef::DType, MemoryRegion::L0B>(byteOffset, numElem);
161	        } else if constexpr (TileDef::Loc == TileType::Acc) {
162	            return GetPointer<typename TileDef::DType, MemoryRegion::L0C>(byteOffset, numElem);
163	        } else if constexpr (TileDef::Loc == TileType::ScaleLeft) {
164	            return GetPointer<typename TileDef::DType, MemoryRegion::L0A_MX>(byteOffset, numElem);
165	        } else if constexpr (TileDef::Loc == TileType::ScaleRight) {
166	            return GetPointer<typename TileDef::DType, MemoryRegion::L0B_MX>(byteOffset, numElem);
167	        } else {
168	            return GetPointer<typename TileDef::DType, MemoryRegion::UB>(
169	                byteOffset,
170	                numElem); // For Vec and unknown types
171	        }
172	    }
173	
174	    // PTOAS-generated CPU-sim kernels may TASSIGN either:
175	    // - a byte offset within the simulated NPU region, or
176	    // - an already-materialized host pointer to a tile in that region
177	    //   (used when creating another tile view over the same backing storage).
178	    template <typename TileDef>
179	    typename TileDef::DType* ResolveAssignedAddress(std::uintptr_t addr)
180	    {
181	        static_assert(is_tile_data_v<TileDef> || is_conv_tile_v<TileDef>);
182	        EnsureInitialized();
183	
184	        if (auto* direct = TryResolveExistingPointer<typename TileDef::DType>(addr)) {
185	            return direct;
186	        }
187	        return GetPointer<TileDef>(static_cast<std::size_t>(addr));
188	    }
189	
190	    // Get raw buffer bases (for debugging/direct access)
191	    char* GetREGBase()
192	    {
193	        EnsureInitialized();
194	        return buffers_[MemoryRegion::REG].data();
195	    }
196	    char* GetUBBase()
197	    {
198	        EnsureInitialized();
199	        return buffers_[MemoryRegion::UB].data();
200	    }
201	    char* GetL1Base()
202	    {
203	        EnsureInitialized();
204	        return buffers_[MemoryRegion::L1].data();
205	    }
206	    char* GetL0ABase()
207	    {
208	        EnsureInitialized();
209	        return buffers_[MemoryRegion::L0A].data();
210	    }
211	    char* GetL0BBase()
212	    {
213	        EnsureInitialized();
214	        return buffers_[MemoryRegion::L0B].data();
215	    }
216	    char* GetL0CBase()
217	    {
218	        EnsureInitialized();
219	        return buffers_[MemoryRegion::L0C].data();
220	    }
221	
222	    const NPUMemoryModel::ArchMemorySizes& GetSizes() const { return sizes_; }
223	    NPUArch GetArch() const { return arch_; }
224	    bool IsInitialized() const { return initialized_; }
225	
226	    // Clear all memory (zero-fill)
227	    void Clear()
228	    {
229	        if (initialized_) {
230	            for (auto& buf : buffers_) {
231	                std::fill(buf.begin(), buf.end(), 0);
232	            }
233	        }
234	    }
235	
236	    // Reset to uninitialized state
237	    void Reset()
238	    {
239	        for (auto& buf : buffers_) {
240	            buf.clear();
241	        }
242	        initialized_ = false;
243	    }
244	
245	private:
246	    template <typename T>
247	    T* TryResolveExistingPointer(std::uintptr_t addr)
248	    {
249	        for (int region = 0; region < MemoryRegion::_MAX_REGIONS; ++region) {
250	            auto* base = buffers_[region].data();
251	            const auto start = reinterpret_cast<std::uintptr_t>(base);
252	            const auto end = start + buffers_[region].size();
253	            if (addr >= start && addr < end) {
254	                return reinterpret_cast<T*>(addr);
255	            }
256	        }
257	        return nullptr;
258	    }
259	
260	    template <typename T, MemoryRegion region>
261	    inline T* GetPointer(std::size_t byteOffset, size_t numel)
262	    {
263	        EnsureInitialized();
264	
265	        assert(byteOffset + numel * sizeof(T) <= sizes_[region]);
266	        return reinterpret_cast<T*>(buffers_[region].data() + byteOffset);
267	    }
268	
269	    NPUMemoryModel() = default;
270	    NPUMemoryModel(const NPUMemoryModel&) = delete;
271	    NPUMemoryModel(const NPUMemoryModel&&) = delete;
272	
273	    // Shared default architecture — set once, read by all threads during auto-init
274	    static inline NPUArch defaultArch_ = NPUArch::A2A3;
275	
276	    // Per-thread memory buffers (thread_local instance owns these)
277	    std::vector<char> buffers_[MemoryRegion::_MAX_REGIONS];
278	
279	    ArchMemorySizes sizes_ = {};
280	    NPUArch arch_ = NPUArch::A2A3;
281	    bool initialized_ = false;
282	};
283	
284	constexpr uint32_t SHIFT_MX_ADDR = 4;
285	template <typename T>
286	uint64_t GetScaleAddr(T* dst)
287	{
288	    uintptr_t addr = NPUMemoryModel::Instance().GetNPUAddr(dst);
289	    return addr >> SHIFT_MX_ADDR;
290	}
291	
292	} // namespace pto
293	
294	#endif // PTO_NPU_MEMORY_MODEL_HPP
