namespace pto::cpu {

inline unsigned get_thread_count() noexcept
{
    unsigned hw = std::thread::hardware_concurrency();
    if (hw == 0) {
        hw = 1;
    }
    if constexpr (PTO_CPU_MAX_THREADS != 0u) {
        hw = std::min<unsigned>(hw, PTO_CPU_MAX_THREADS);
